-- V19: monetary reservations are serialized by locking the invoice row in application code.\n-- These constraints protect against duplicate workflow attempts and invalid negative reservations.\nALTER TABLE payment_application\n  ADD CONSTRAINT ck_payment_application_amount_requested_positive CHECK (amount_requested > 0),\n  ADD CONSTRAINT ck_payment_application_amount_approved_positive CHECK (amount_approved IS NULL OR amount_approved > 0);\nALTER TABLE payment\n  ADD CONSTRAINT ck_payment_amount_positive CHECK (amount > 0);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_payment_one_per_application\n  ON payment (tenant_id, payment_application_id);\nCREATE INDEX IF NOT EXISTS ix_payment_application_invoice_status\n  ON payment_application (tenant_id, invoice_id, status);\nCREATE INDEX IF NOT EXISTS ix_payment_invoice_status\n  ON payment (tenant_id, invoice_id, status);